<div class="editor-grid"><section class="editor-main"><label>Coupon code<input name="code" value="{{ old('code', optional($coupon)->code) }}" placeholder="WELCOME15" required></label><div class="two-col"><label>Discount type<select name="type"><option value="percentage" {{ old('type', optional($coupon)->type) === 'percentage' ? 'selected' : '' }}>Percentage</option><option value="fixed" {{ old('type', optional($coupon)->type) === 'fixed' ? 'selected' : '' }}>Fixed amount</option></select></label><label>Value<input type="number" name="value" step="0.01" min="0" value="{{ old('value', optional($coupon)->value) }}" required></label></div><label>Eligible products<select name="scope" id="scope"><option value="all" {{ old('scope', optional($coupon)->scope ?? 'all') === 'all' ? 'selected' : '' }}>All products</option><option value="category" {{ old('scope', optional($coupon)->scope) === 'category' ? 'selected' : '' }}>One category</option><option value="products" {{ old('scope', optional($coupon)->scope) === 'products' ? 'selected' : '' }}>Specific products</option></select></label><label id="category-target">Category<select name="category_id"><option value="">Select a category</option>@foreach($categories as $category)<option value="{{ $category->id }}" {{ old('category_id', optional($coupon)->category_id) == $category->id ? 'selected' : '' }}>{{ $category->name }}</option>@endforeach</select></label><label id="product-target">Products<select name="product_ids[]" multiple size="5">@foreach($products as $product)<option value="{{ $product->id }}" {{ in_array($product->id, old('product_ids', optional($coupon)->product_ids ?? [])) ? 'selected' : '' }}>{{ $product->name }}</option>@endforeach</select></label></section><aside class="editor-side"><label>Minimum cart value<input type="number" name="min_cart_value" step="0.01" min="0" value="{{ old('min_cart_value', optional($coupon)->min_cart_value) }}" placeholder="0.00"></label><label>Usage limit<input type="number" name="usage_limit" min="1" value="{{ old('usage_limit', optional($coupon)->usage_limit) }}" placeholder="Unlimited"></label><label>Expires at<input type="datetime-local" name="expires_at" value="{{ old('expires_at', optional($coupon)->expires_at ? $coupon->expires_at->format('Y-m-d\\TH:i') : '') }}"></label><label class="check"><input type="checkbox" name="is_active" value="1" {{ old('is_active', optional($coupon)->is_active ?? true) ? 'checked' : '' }}> Active coupon</label></aside></div>@if($errors->any())<div class="error">{{ $errors->first() }}</div>@endif<button class="button button-accent save-button" type="submit">Save coupon <span>→</span></button><script>const scope=document.querySelector('#scope');const targets=()=>{document.querySelector('#category-target').style.display=scope.value==='category'?'block':'none';document.querySelector('#product-target').style.display=scope.value==='products'?'block':'none'};scope.addEventListener('change',targets);targets();</script>